<script setup>
import {ref} from 'vue';import {useRouter} from 'vue-router';import {login,register} from '../api/auth'
const router=useRouter(),mode=ref('login'),username=ref(''),email=ref(''),password=ref(''),error=ref(''),loading=ref(false)
async function submit(){if(loading.value)return;error.value='';if(username.value.trim().length<3||password.value.length<6){error.value='用户名至少3位，密码至少6位';return}loading.value=true;try{const res=mode.value==='login'?await login({username:username.value.trim(),password:password.value}):await register({username:username.value.trim(),email:email.value.trim(),password:password.value});localStorage.setItem('englishmate.token',res.data.token);localStorage.setItem('englishmate.user',JSON.stringify({username:res.data.username,userId:res.data.userId}));router.push('/')}catch(e){error.value=e.response?.data?.message||'操作失败，请检查后端服务'}finally{loading.value=false}}
</script>
<template><main class="auth"><section class="card"><div class="brand">EnglishMate</div><h1>{{mode==='login'?'欢迎回来':'创建学习账号'}}</h1><p>登录后，你的聊天、作文、错题和学习档案都会按账号独立保存。</p><div class="tabs"><button :class="{on:mode==='login'}" @click="mode='login'">登录</button><button :class="{on:mode==='register'}" @click="mode='register'">注册</button></div><input v-model="username" placeholder="用户名" @keyup.enter="submit"><input v-if="mode==='register'" v-model="email" type="email" placeholder="邮箱"><input v-model="password" type="password" placeholder="密码（至少6位）" @keyup.enter="submit"><div v-if="error" class="error">{{error}}</div><button class="submit" :disabled="loading" @click="submit">{{loading?'提交中…':mode==='login'?'登录':'注册并登录'}}</button></section></main></template>
<style scoped>.auth{min-height:100vh;display:grid;place-items:center;padding:24px;background:linear-gradient(145deg,#f5f7ff,#eef4ff)}.card{width:min(440px,100%);padding:34px;border:1px solid #e4e7f2;border-radius:26px;background:white;box-shadow:0 24px 70px rgba(70,78,130,.12)}.brand{font-weight:850;color:#5b5cf0}.card h1{margin:14px 0 6px}.card p{color:#7c8497;line-height:1.7}.tabs{display:grid;grid-template-columns:1fr 1fr;background:#f4f5fb;border-radius:13px;padding:4px;margin:24px 0 16px}.tabs button{padding:10px;border:0;background:transparent;border-radius:10px}.tabs .on{background:white;box-shadow:0 4px 12px #dfe2ef}.card input{width:100%;box-sizing:border-box;margin-top:12px;padding:14px 15px;border:1px solid #dfe3ef;border-radius:13px;outline:none}.card input:focus{border-color:#7778ee}.submit{width:100%;margin-top:16px;padding:14px;border:0;border-radius:13px;color:white;background:#5b5cf0;font-weight:750}.error{margin-top:12px;color:#c33;font-size:13px}</style>
